    letter-spacing: 0.1em;
    font-weight: 600;
    margin-bottom: 0.75rem;
}

.editorial-title {
    font-size: 1.25rem;
    font-weight: 700;
    margin-bottom: 0.75rem;
    line-height: 1.4;
}

.editorial-excerpt {
    color: var(--text-secondary);
    font-size: 0.95rem;
    margin-bottom: 1rem;
    flex-grow: 1;
    line-height: 1.5;
}

.read-more {
