    background: linear-gradient(45deg, transparent 30%, rgba(88, 166, 255, 0.05) 50%, transparent 70%);
    animation: shimmer 3s infinite;
}

@keyframes shimmer {
    0% { transform: translateX(-100%); }
    100% { transform: translateX(100%); }
}

.product-badge {
    position: absolute;
    top: 1rem;
    right: 1rem;
    background-color: var(--error);
    color: var(--text-primary);
    padding: 0.5rem 1rem;
    border-radius: 20px;
    font-size: 0.875rem;
    font-weight: 600;
    z-index: 1;
}

.product-info {
    padding: 1.5rem;
    flex-grow: 1;
    display: flex;
    flex-direction: column;
}

.product-category {
    color: var(--text-tertiary);
    font-size: 0.875rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: 0.5rem;
}

.product-name {
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: 0.5rem;
    line-height: 1.4;
}

.product-description {
    color: var(--text-secondary);
    font-size: 0.9rem;
    margin-bottom: 1rem;
    flex-grow: 1;
}

.product-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.product-price {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.price {
    font-size: 1.25rem;
    font-weight: 700;
}

.original-price {
    color: var(--text-tertiary);
    text-decoration: line-through;
    font-size: 0.9rem;
}

.product-rating {
    color: var(--accent-gold);
    font-size: 0.9rem;
}

.add-to-cart-btn {
    background-color: var(--accent-primary);
    color: var(--text-primary);
    border: none;
    padding: 0.625rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
    font-weight: 600;
    font-size: 0.875rem;
    transition: all 0.3s ease;
}

.add-to-cart-btn:hover {
    background-color: var(--accent-secondary);
    transform: scale(1.05);
}

/* Deal Card */
.deal-card {
    background: linear-gradient(135deg, var(--bg-tertiary) 0%, var(--bg-secondary) 100%);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    padding: 2rem;
    text-align: center;
    transition: all 0.3s ease;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}

.deal-card:hover {
    border-color: var(--accent-gold);
    box-shadow: 0 12px 24px rgba(212, 175, 55, 0.15);
    transform: translateY(-4px);
}

.deal-title {
    font-size: 1.5rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
}

.deal-description {
    color: var(--text-secondary);
    margin-bottom: 1.5rem;
}

.deal-discount {
    font-size: 2.5rem;
    color: var(--accent-gold);
    font-weight: 700;
    margin-bottom: 1rem;
}

.deal-timer {
    color: var(--text-tertiary);
    font-size: 0.9rem;
    margin-bottom: 1.5rem;
}

/* Editorial Card */
.editorial-card {
    background-color: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    overflow: hidden;
    transition: all 0.3s ease;
    display: flex;
    flex-direction: column;
}

.editorial-card:hover {
    border-color: var(--accent-primary);
    box-shadow: 0 12px 24px rgba(88, 166, 255, 0.15);
    transform: translateY(-4px);
}

.editorial-image {
    width: 100%;
    height: 250px;
    background: linear-gradient(135deg, var(--bg-tertiary) 0%, var(--bg-primary) 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--text-tertiary);
    font-size: 2.5rem;
}

.editorial-content {
    padding: 1.5rem;
    flex-grow: 1;
    display: flex;
    flex-direction: column;
}

.editorial-tag {
    color: var(--accent-primary);
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 600;
    margin-bottom: 0.75rem;
}

.editorial-title {
    font-size: 1.25rem;
    font-weight: 700;
    margin-bottom: 0.75rem;
    line-height: 1.4;
}

.editorial-excerpt {
    color: var(--text-secondary);
    font-size: 0.95rem;
    margin-bottom: 1rem;
    flex-grow: 1;
    line-height: 1.5;
}

.read-more {
    color: var(--accent-primary);
    font-weight: 600;
    text-decoration: none;
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    transition: gap 0.3s ease;
}

.read-more:hover {
    gap: 0.75rem;
}

/* Newsletter Section */
.newsletter {
    background: linear-gradient(135deg, var(--bg-tertiary) 0%, var(--bg-secondary) 100%);
    padding: 4rem 2rem;
    margin: 0;
    border-bottom: 1px solid var(--border-color);
}

.newsletter-content {
    max-width: 600px;
    margin: 0 auto;
    text-align: center;
}

.newsletter-content h3 {
    font-size: 2rem;
    margin-bottom: 0.5rem;
}

.newsletter-content p {
    color: var(--text-secondary);
    margin-bottom: 2rem;
}

.newsletter-form {
    display: flex;
    gap: 1rem;
    margin-bottom: 1rem;
}

.newsletter-form input {
    flex: 1;
    padding: 0.875rem 1.25rem;
    background-color: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: 6px;
    color: var(--text-primary);
    font-size: 1rem;
    transition: all 0.3s ease;
}

.newsletter-form input::placeholder {
    color: var(--text-tertiary);
}

.newsletter-form input:focus {
    outline: none;
    border-color: var(--accent-primary);
    box-shadow: 0 0 0 3px rgba(88, 166, 255, 0.1);
}

/* Footer */
.footer {
    background-color: var(--bg-primary);
    padding: 3rem 2rem 1.5rem;
    border-top: 1px solid var(--border-color);
}

.footer-content {
    max-width: 1400px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 2rem;
    margin-bottom: 2rem;
}

.footer-section h4 {
    font-size: 1rem;
    font-weight: 600;
    margin-bottom: 1rem;
    color: var(--text-primary);
}

.footer-section ul {
    list-style: none;
}

.footer-section a {
    color: var(--text-secondary);
    text-decoration: none;
    display: block;
    padding: 0.5rem 0;
    transition: color 0.3s ease;
}

.footer-section a:hover {
    color: var(--accent-primary);
}

.social-links {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
}

.social-link {
    display: inline-block !important;
    padding: 0.25rem !important;
}

.footer-bottom {
    max-width: 1400px;
    margin: 0 auto;
    padding-top: 1.5rem;
    border-top: 1px solid var(--border-color);
    text-align: center;
    color: var(--text-tertiary);
    font-size: 0.9rem;
}

/* Responsive */
@media (max-width: 768px) {
    .nav-links {
        display: none;
    }

    .hero {
        grid-template-columns: 1fr;
        padding: 3rem 1.5rem;
    }

    .hero-title {
        font-size: 2.25rem;
    }

    .hero-subtitle {
        font-size: 1rem;
    }

    .hero-placeholder {
        height: 300px;
    }

    .products-grid,
    .deals-grid,
    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .featured-products,
    .deals-section,
    .editorial-section,
    .newsletter {
        padding: 2rem 1.5rem;
    }

    .section-header h2 {
        font-size: 1.75rem;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form button {
        width: 100%;
    }
}

@media (max-width: 480px) {
    .navbar-container {
        padding: 1rem;
    }

    .logo {
        font-size: 1.25rem;
    }

    .nav-icons {
        gap: 0.5rem;
    }

    .icon-btn svg {
        width: 20px;
        height: 20px;
    }

    .hero-title {
        font-size: 1.75rem;
    }

    .section-header h2 {
        font-size: 1.5rem;
    }
}

